// ── the digest issue ─────────────────────────────────────────────────────────

// One markdown-table-safe line: severity-line stripped, whitespace
// collapsed, capped, pipes escaped.
function oneLine(text) {
    var s = reviewVerdicts.stripLeadingSeverityLine(String(text || ''))
        .replace(/\s+/g, ' ').trim();
